package gateway
import("encoding/json";"strings";"testing";"net/http/httptest";"time")
func TestLexOpenGitHubPersistentImportWebDeviceAndLegacy(t *testing.T){for _,public:=range []bool{false,true}{t.Run(map[bool]string{false:"web",true:"device"}[public],func(t *testing.T){server,fleet:=lexopenOAuthServer(t);name:="altazor-github-abcdef0123456789";body:=map[string]any{"kind":"github","client_id":"fixture-github-client","client_secret":"fixture-github-secret","access_token":"fixture-github-access","refresh_token":"fixture-github-refresh","expires_at":time.Now().Add(8*time.Hour),"scopes":[]string{"read:user"},"account":"12345","public_client":public};if public{body["client_secret"]=""};r:=lexopenOAuthRequest(server,"/v1/lexopen/easy-oauth/"+name,body,"127.0.0.1:43210","fixture-gateway-token");if r.Code!=200||strings.Contains(r.Body.String(),"fixture-github-"){t.Fatal("new expiring import rejected or leaked")};app,e:=fleet.OAuthApp(name);if e!=nil||app.Settings["oauth_lexopen_github_refresh"]!="v1"||app.Settings["oauth_scopes"]!="read:user"{t.Fatal("refresh contract not pinned")};c,e:=fleet.OAuthCredentials(name);if e!=nil||c.RefreshToken!="fixture-github-refresh"{t.Fatal("pair not imported")};for _,alter:=range []func(map[string]any){func(v map[string]any){delete(v,"refresh_token")},func(v map[string]any){delete(v,"expires_at")},func(v map[string]any){v["expires_at"]=time.Now().Add(30*time.Second)},func(v map[string]any){v["scopes"]=[]string{"read:user","repo"}},func(v map[string]any){v["kind"]="dropbox"},func(v map[string]any){if public{v["client_secret"]="not-allowed"}else{v["client_secret"]=""}}}{raw,_:=json.Marshal(body);var bad map[string]any;json.Unmarshal(raw,&bad);alter(bad);rr:=lexopenOAuthRequest(server,"/v1/lexopen/easy-oauth/"+name,bad,"127.0.0.1:43210","fixture-gateway-token");if rr.Code!=400{t.Fatal("invalid expiring import accepted")}}})};now:=time.Now();legacy:=lexopenOAuthImport{Kind:"github",ClientID:"client",ClientSecret:"secret",AccessToken:"static",Scopes:[]string{"read:user"}};app,_,ok:=legacy.validate("altazor-github-0123456789abcdef",now);if !ok||app.Settings["oauth_lexopen_github_refresh"]!=""{t.Fatal("legacy nonexpiring behavior changed")}}
func TestLexOpenGitHubPersistentHealthCapability(t *testing.T){server,_:=stagedGatewayFixture();rec:=httptest.NewRecorder();server.ServeHTTP(rec,httptest.NewRequest("GET","/v1/health",nil));var result map[string]any;if rec.Code!=200||json.Unmarshal(rec.Body.Bytes(),&result)!=nil{t.Fatal("health failed")};for _,key:=range []string{"lexopen_github_persistent_oauth","lexopen_cloud_metadata","lexopen_connected_file_focus","lexopen_cloud_file_oauth","lexopen_oauth_alias_create","lexopen_persistent_oauth","lexopen_staged_file_actions"}{if result[key]!="v1"{t.Fatal("missing current/prior capability",key)}}}
